/// The table (the C++ shim's `mTable`).
struct EeCpInfluence;

/// An open scope that records (one exists only while the capture is on and the scope is its thread's outermost).
struct EeCpPlaceScope;

/// The class's own data (the C++ object owns it: `EECPPlacement::mRust`).
struct EeCpPlacement;

/// One record of the behaviour table (`EECPBehavior`, ee/EECPBehavior.h: 56 bytes).
struct EeCpBehavior {
  int32_t unused1;
  /// the slot (records with index <= 0 are skipped)
  int32_t index;
  int32_t i1_min;
  int32_t i1_max;
  /// `mIntValue1`
  int32_t i1;
  int32_t i2_min;
  int32_t i2_max;
  /// `mIntValue2`
  int32_t i2;
  int32_t unused2;
  int32_t float_min;
  int32_t float_max;
  int32_t float_scale;
  /// `mFloatValue`
  float fv;
  bool settable;
};

/// What a load read past the fields: the running state of a 0.256-or-later save (the caller puts it back at the
/// first tick) and whether the fields read without an error before it.
struct EeCpLoaded {
  /// the result was kErrorOK after the favourite space type (the original registered the favourites' restore
  /// there, for a 0.254-or-later save)
  bool favorites_ok;
  /// the running state below was read
  bool running;
  long population_cap;
  bool enable_time_set;
  bool regroup_pending;
  long next_population_time;
  long last_damaged_time;
};

/// The game's generator for [`ee_cp_set_next_attack_time`]: `GetRandom(min, max)`.
using EeCpRandomFn = long(*)(void *ctx, long min, long max);

/// A rectangle of regions or tiles, edges included (`U2DRectangle<long>`).
struct EeCpRect {
  int32_t left;
  int32_t top;
  int32_t right;
  int32_t bottom;
};

/// A unit as the herd reads it (`EEComplexUnit` and its class; one host call).
struct EeHerdUnit {
  /// `mUnitID`
  unsigned long unit_id;
  /// `EEUnitHandleID`: what a handle to it holds
  uint32_t handle;
  long tile_x;
  long tile_y;
  long hit_points;
  float growth;
  unsigned long graze_time;
  unsigned long grow_time;
  /// `mCommand ? mCommand->mType : 0`
  long command;
  /// `mWaypoints.size()`
  int64_t waypoints;
  /// `mHeldUnits.size()`
  int64_t held;
  /// `mHolder`
  uint64_t holder;
  /// `mHerd` (`EEHerd*`)
  uint64_t herd;
  /// `mPlayer`
  uint64_t player;
  uint64_t last_attacker;
  /// `mStats->mModel` (its `EEMedia`)
  uint64_t model;
  /// the class's `mAttack`, `mAmmoType`, `mFamily`, `mAnimalID`
  long attack;
  long ammo_type;
  unsigned long family;
  long animal_id;
  bool disabled;
  /// `mStats->mIsInitialized`
  bool initialized;
  /// `GetGoal() != NULL`
  bool has_goal;
  bool regrowing;
  bool b34f;
  /// the class's `CanBeAttacked()`
  bool can_be_attacked;
};

/// One host operation's values.
struct EeHerdIo {
  int64_t v[6];
  float f[4];
  EeHerdUnit unit;
  /// the units an operation reads (`EEComplexUnit*`)
  const uint64_t *input;
  size_t input_len;
  /// the lists an operation pushes onto (`ee_cp_herd_push`: four values a row)
  void *list;
  void *list2;
};

/// A favourite types' history entry: (unit type, epoch).
struct EeCpHistoryEntry {
  unsigned long unit_type;
  long epoch;
};

/// A danger zone: a tile and the game time it was noted.
struct EeCpDangerZone {
  long x;
  long y;
  unsigned long time;
};

/// What the C++ hands every call: the computer player and its placement.
struct EeCpPlaceCtx {
  /// the `EEComputerPlayer*` (its `EEPlayer*`: the first base)
  uint64_t player;
  /// `mPlayerID`
  uint32_t player_id;
  /// the player's record (`static_cast<EeCpFields*>(player)`)
  EeCpFields *fields;
  /// `mPlacement->mTownCenterTile`'s `mX`, `mY` (null: no placement)
  long *town;
  /// `mPlacement->mRust` (null: no placement)
  EeCpPlacement *placement;
  /// `EESimCaptureRecord::Active()`: the tile lists go through the noted entry points (their TEST ONLY notes)
  uint8_t capture;
};

/// One unit's members the searches read (`UNIT_INFO`; a null unit reads as `Default`).
struct EeCpUnitInfo {
  /// `mTileX`, `mTileY`
  int32_t tile[2];
  /// `mUnitID`
  uint32_t id;
  /// `mUnitClass->mUnitType`, `GetTileSize()`, `mCategory`, `mFamily`, `mTechnology`
  int32_t unit_type;
  int32_t tile_size;
  int32_t category;
  int32_t family;
  int32_t technology;
  /// `mHitPoints`, `mResourceAmount`, `mResourceType`
  int32_t hit_points;
  int32_t resource_amount;
  int32_t resource_type;
  /// `mComplexUnit` (0: none) and, when there is one, its `mTileX`, `mTileY`, `mHitPoints`, `mIsBuilt`, `mFacing`,
  /// `mPreviousPart`, `mNextPart`
  uint64_t complex;
  int32_t complex_tile[2];
  int32_t complex_hit_points;
  uint8_t complex_built;
  /// `mIsValid`, `mTile != NULL`, `GetTileNode() != NULL`, `mUnitClass->IsLandBuilding()`, `mIsWall`, `IsDropSite()`
  uint8_t valid;
  uint8_t has_tile;
  uint8_t has_tile_node;
  uint8_t land_building;
  uint8_t wall;
  uint8_t drop_site;
  uint8_t has_class;
  uint32_t facing;
  uint64_t previous_part;
  uint64_t next_part;
  /// `mPlayer` (the owner's `EEPlayer*`)
  uint64_t player;
};

/// One host operation's values.
struct EeCpPlaceIo {
  /// up to six integer arguments and results
  int64_t v[6];
  /// float results
  float f[3];
  /// UNIT_INFO's result
  EeCpUnitInfo unit;
  /// the list an operation starts from (`input_len` pairs; the sort's keys: `input_len` single values)
  const int64_t *input;
  size_t input_len;
  /// the list an operation pushes onto (`ee_cp_place_push`)
  void *list;
  /// the sort's order out (`input_len` indices)
  uint32_t *order;
};

/// What `EECPNextPlaceSearch` returns: found, x, y, gap.
struct EeCpPlaceResult {
  uint8_t found;
  int32_t x;
  int32_t y;
  int32_t gap;
};

/// One `EEPUnitSwap` (`mOld`, `mNew`).
struct EeCpUnitSwap {
  uint64_t old;
  uint64_t new_;
};

/// One host operation's values.
struct TownIo {
  int64_t v[8];
  /// the points an operation reads (x, y pairs)
  const int64_t *input;
  size_t input_len;
  /// the list an operation pushes onto (`ee_cp_herd_push`: four values a row)
  void *list;
};

/// `EECPPlacement` (ee/EECPPlacement.h, a view of this record; the original's build manager, of which only the town
/// centre tile, the player and the Rust placement are left): made by `Init`, freed by the destructor.
struct EeCpPlacementObj {
  /// `mTownCenterTile` (-10000, -10000: none)
  long town[2];
  /// `mPlayer` (the `EEComputerPlayer*`)
  void *player;
  /// `mRust`: the site tiles and the classes seen (place_game.rs)
  EeCpPlacement *rust;
};

